<?php namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; class ProfileController extends Controller { public function show(Request $r){return ['data'=>$r->user()];} public function update(Request $r){$u=$r->user();$u->update($r->validate(['name'=>'required|string|max:100','phone'=>'nullable|string|max:30']));return ['data'=>$u];} public function password(Request $r){$d=$r->validate(['current_password'=>'required','password'=>'required|min:8|confirmed']);abort_unless(Hash::check($d['current_password'],$r->user()->password),422);$r->user()->update(['password'=>$d['password']]);return response()->noContent();} }
